CREATE TABLE IF NOT EXISTS roles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(32) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS permissions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(64) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS user_roles (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY (user_id,role_id));
CREATE TABLE IF NOT EXISTS role_permissions (role_id BIGINT NOT NULL, permission_id BIGINT NOT NULL, PRIMARY KEY (role_id,permission_id));
CREATE TABLE IF NOT EXISTS revoked_tokens (token_id VARCHAR(64) PRIMARY KEY, expires_at TIMESTAMP NOT NULL);
MERGE INTO roles (code) KEY(code) VALUES ('user'),('merchant'),('admin');
MERGE INTO permissions (code) KEY(code) VALUES ('profile:write'),('pet:write'),('shop:order'),('merchant:manage'),('admin:manage');
INSERT INTO role_permissions (role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON
  (r.code='user' AND p.code IN ('profile:write','pet:write','shop:order')) OR
  (r.code='merchant' AND p.code IN ('profile:write','merchant:manage')) OR (r.code='admin');
